/* The website and full laboratory share one v2 save. The homepage is an observer, not a second simulator. */
(()=>{'use strict';let world=SocietySession.load();const art=new Image();art.src='assets/footer.png';
function mount(){const route=location.hash.replace(/^#\/?/,'').split('/')[0];if(route==='village'){document.querySelector('main').innerHTML='<div class="pageheading"><h1>The village</h1><p>Follow people, production and the agreements connecting them.</p><a href="lab.html" class="button">Open full screen ↗</a></div><iframe src="lab.html?embedded=1" title="Interactive society simulation" style="width:100%;height:1450px;border:0;display:block" loading="eager"></iframe>';return}if(route===''||route==='play'){const hill=document.querySelector('.hill');if(hill)hill.outerHTML='<section class="live-hill"><canvas class="game-scene" id="shared-hill" aria-label="Up to five residents from the saved village"></canvas><div class="hill-caption"><span>Five residents visiting the hill</span><a href="#/village">Enter the village →</a></div></section>';world=SocietySession.load()}}
function frame(now){const canvas=document.getElementById('shared-hill');if(canvas){const rect=canvas.getBoundingClientRect(),ratio=devicePixelRatio||1;canvas.width=Math.round(rect.width*ratio);canvas.height=Math.round(rect.height*ratio);const c=canvas.getContext('2d');c.scale(ratio,ratio);if(art.complete&&art.naturalWidth)c.drawImage(art,0,0,rect.width,rect.height);const circle=world.s.groups.find(g=>g.kind==='circle'),ids=[...(circle?.members||[]),...world.s.agents.map(a=>a.id)],agents=[...new Set(ids)].slice(0,5).map(id=>world.agent(id));for(let i=0;i<agents.length;i++){const a=agents[i],x=rect.width*(.15+i*.17),y=rect.height*.8;if(CreatureArt.ready)CreatureArt.sprite(c,a.kind,x,y,Math.min(90,rect.height*.34),'idle',now/1000);const hat=world.currentHat(a);if(hat){c.fillStyle=hat.color;c.fillRect(x-9,y-Math.min(90,rect.height*.34),18,7)}c.fillStyle='#17334b';c.font='13px system-ui';c.textAlign='center';c.fillText(a.name,x,y+17)}}requestAnimationFrame(frame)}
window.addEventListener('hashchange',mount);window.addEventListener('storage',e=>{if(e.key===SocietySession.KEY)world=SocietySession.load()});mount();requestAnimationFrame(frame);
})();
